// Generated by /ship test coverage audit.
// Value: protects=parseRoute maps hash routes to views/pages and falls back to Home for unknown or slug-less routes;
//   fails_when=the fallback, empty-slug guard or '#/' stripping regresses (blank screen or wrong page);
//   why_new=e2e covers only happy-path routes and /page/does-not-exist; seam=none
// Value: protects=slugify yields URL-safe city slugs; fails_when=spaces/punctuation or edge dashes leak into slugs;
//   why_new=no direct test; e2e clicks one city only; seam=none
import { describe, expect, it } from 'vitest';
import { parseRoute, slugify, type ParsedRoute } from './routes';

describe('parseRoute', () => {
  it.each<[string, ParsedRoute]>([
    ['home', { kind: 'view', view: 'home' }],
    ['vendor', { kind: 'view', view: 'vendor' }],
    ['#/pricing', { kind: 'view', view: 'pricing' }],
    ['/ops', { kind: 'view', view: 'ops' }],
    ['page/about', { kind: 'page', slug: 'about' }],
    ['#/near/rice', { kind: 'near', slug: 'rice' }],
    ['city/port-harcourt', { kind: 'city', slug: 'port-harcourt' }],
    ['page/a/b', { kind: 'page', slug: 'a/b' }],
    // fallbacks: never a blank screen
    ['', { kind: 'view', view: 'home' }],
    ['nope', { kind: 'view', view: 'home' }],
    ['page', { kind: 'view', view: 'home' }],
    ['page/', { kind: 'view', view: 'home' }],
    ['near/', { kind: 'view', view: 'home' }],
    ['Vendor', { kind: 'view', view: 'home' }],
  ])('%j → %j', (route, expected) => {
    expect(parseRoute(route)).toEqual(expected);
  });
});

describe('slugify', () => {
  it.each([
    ['Port Harcourt', 'port-harcourt'],
    ['Lagos', 'lagos'],
    ['  Fast food!! ', 'fast-food'],
    ['Abia & Co.', 'abia-co'],
    ['---', ''],
  ])('%j → %j', (input, expected) => {
    expect(slugify(input)).toBe(expected);
  });
});
